{"p": "code", "f": "code-files.html", "ty": "code-file", "ti": "Polymorphism.cpp", "cx": "", "tab": "poly"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "Polymorphism.cpp", "tab": "poly", "ln": 1, "tx": "#include<iostream>"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "Polymorphism.cpp", "tab": "poly", "ln": 2, "tx": "#include<string>"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "Polymorphism.cpp", "tab": "poly", "ln": 3, "tx": "using namespace std;"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "Polymorphism.cpp", "tab": "poly", "ln": 5, "tx": "// Abstract class: it has a pure virtual function, so no Shape objects"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "Polymorphism.cpp", "tab": "poly", "ln": 6, "tx": "class Shape {"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "Polymorphism.cpp", "tab": "poly", "ln": 7, "tx": "public:"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "Polymorphism.cpp", "tab": "poly", "ln": 8, "tx": "    virtual double area() const = 0;         // pure virtual"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "Polymorphism.cpp", "tab": "poly", "ln": 9, "tx": "    virtual string name() const { return \"Shape\"; }"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "Polymorphism.cpp", "tab": "poly", "ln": 10, "tx": "    virtual ~Shape() { cout << \"~Shape\" << endl; }   // virtual destructor!"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "Polymorphism.cpp", "tab": "poly", "ln": 11, "tx": "};"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "Polymorphism.cpp", "tab": "poly", "ln": 13, "tx": "class Circle : public Shape {"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "Polymorphism.cpp", "tab": "poly", "ln": 14, "tx": "private:"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "Polymorphism.cpp", "tab": "poly", "ln": 15, "tx": "    double r_;"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "Polymorphism.cpp", "tab": "poly", "ln": 16, "tx": "public:"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "Polymorphism.cpp", "tab": "poly", "ln": 17, "tx": "    Circle(double r) : r_(r) {}"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "Polymorphism.cpp", "tab": "poly", "ln": 18, "tx": "    double area() const override { return 3.14159 * r_ * r_; }"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "Polymorphism.cpp", "tab": "poly", "ln": 19, "tx": "    string name() const override { return \"Circle\"; }"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "Polymorphism.cpp", "tab": "poly", "ln": 20, "tx": "    ~Circle() { cout << \"~Circle\" << endl; }"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "Polymorphism.cpp", "tab": "poly", "ln": 21, "tx": "};"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "Polymorphism.cpp", "tab": "poly", "ln": 23, "tx": "class Rectangle : public Shape {"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "Polymorphism.cpp", "tab": "poly", "ln": 24, "tx": "private:"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "Polymorphism.cpp", "tab": "poly", "ln": 25, "tx": "    double w_, h_;"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "Polymorphism.cpp", "tab": "poly", "ln": 26, "tx": "public:"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "Polymorphism.cpp", "tab": "poly", "ln": 27, "tx": "    Rectangle(double w, double h) : w_(w), h_(h) {}"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "Polymorphism.cpp", "tab": "poly", "ln": 28, "tx": "    double area() const override { return w_ * h_; }"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "Polymorphism.cpp", "tab": "poly", "ln": 29, "tx": "    string name() const override { return \"Rectangle\"; }"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "Polymorphism.cpp", "tab": "poly", "ln": 30, "tx": "    ~Rectangle() { cout << \"~Rectangle\" << endl; }"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "Polymorphism.cpp", "tab": "poly", "ln": 31, "tx": "};"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "Polymorphism.cpp", "tab": "poly", "ln": 33, "tx": "// Works for ANY shape: which area() runs is decided at runtime"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "Polymorphism.cpp", "tab": "poly", "ln": 34, "tx": "void describe(const Shape& s) {"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "Polymorphism.cpp", "tab": "poly", "ln": 35, "tx": "    cout << s.name() << \" area: \" << s.area() << endl;"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "Polymorphism.cpp", "tab": "poly", "ln": 36, "tx": "}"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "Polymorphism.cpp", "tab": "poly", "ln": 38, "tx": "int main() {"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "Polymorphism.cpp", "tab": "poly", "ln": 39, "tx": "    // Shape s;                              // error: Shape is abstract"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "Polymorphism.cpp", "tab": "poly", "ln": 41, "tx": "    Shape* shapes[3];                        // base-class pointers..."},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "Polymorphism.cpp", "tab": "poly", "ln": 42, "tx": "    shapes[0] = new Circle(1);               // ...to derived objects"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "Polymorphism.cpp", "tab": "poly", "ln": 43, "tx": "    shapes[1] = new Rectangle(2, 3);"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "Polymorphism.cpp", "tab": "poly", "ln": 44, "tx": "    shapes[2] = new Circle(2);"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "Polymorphism.cpp", "tab": "poly", "ln": 46, "tx": "    for (int i = 0; i < 3; i++)"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "Polymorphism.cpp", "tab": "poly", "ln": 47, "tx": "        describe(*shapes[i]);                // dynamic binding"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "Polymorphism.cpp", "tab": "poly", "ln": 49, "tx": "    for (int i = 0; i < 3; i++)"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "Polymorphism.cpp", "tab": "poly", "ln": 50, "tx": "        delete shapes[i];                    // ~Circle then ~Shape, and so on"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "Polymorphism.cpp", "tab": "poly", "ln": 51, "tx": "}"},
{"p": "code", "f": "code-files.html", "ty": "code-file", "ti": "OperatorOverloading.cpp", "cx": "", "tab": "ops"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "OperatorOverloading.cpp", "tab": "ops", "ln": 1, "tx": "#include<iostream>"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "OperatorOverloading.cpp", "tab": "ops", "ln": 2, "tx": "using namespace std;"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "OperatorOverloading.cpp", "tab": "ops", "ln": 4, "tx": "class Point {"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "OperatorOverloading.cpp", "tab": "ops", "ln": 5, "tx": "private:"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "OperatorOverloading.cpp", "tab": "ops", "ln": 6, "tx": "    int x_, y_;"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "OperatorOverloading.cpp", "tab": "ops", "ln": 7, "tx": "public:"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "OperatorOverloading.cpp", "tab": "ops", "ln": 8, "tx": "    Point(int x = 0, int y = 0) : x_(x), y_(y) {}"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "OperatorOverloading.cpp", "tab": "ops", "ln": 10, "tx": "    // arithmetic: returns a NEW point and leaves *this unchanged (const)"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "OperatorOverloading.cpp", "tab": "ops", "ln": 11, "tx": "    Point operator+(const Point& p) const { return Point(x_ + p.x_, y_ + p.y_); }"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "OperatorOverloading.cpp", "tab": "ops", "ln": 12, "tx": "    Point operator-(const Point& p) const { return Point(x_ - p.x_, y_ - p.y_); }"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "OperatorOverloading.cpp", "tab": "ops", "ln": 14, "tx": "    // compound assignment: changes *this and returns it for chaining"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "OperatorOverloading.cpp", "tab": "ops", "ln": 15, "tx": "    Point& operator+=(const Point& p) { x_ += p.x_; y_ += p.y_; return *this; }"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "OperatorOverloading.cpp", "tab": "ops", "ln": 17, "tx": "    bool operator==(const Point& p) const { return x_ == p.x_ && y_ == p.y_; }"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "OperatorOverloading.cpp", "tab": "ops", "ln": 18, "tx": "    bool operator!=(const Point& p) const { return !(*this == p); }"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "OperatorOverloading.cpp", "tab": "ops", "ln": 20, "tx": "    Point& operator++() { ++x_; ++y_; return *this; }                     // prefix:  ++p"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "OperatorOverloading.cpp", "tab": "ops", "ln": 21, "tx": "    Point operator++(int) { Point old = *this; ++(*this); return old; }  // postfix: p++"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "OperatorOverloading.cpp", "tab": "ops", "ln": 23, "tx": "    // the left operand is NOT a Point, so these must be non-members (friends)"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "OperatorOverloading.cpp", "tab": "ops", "ln": 24, "tx": "    friend Point operator*(int k, const Point& p);"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "OperatorOverloading.cpp", "tab": "ops", "ln": 25, "tx": "    friend ostream& operator<<(ostream& out, const Point& p);"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "OperatorOverloading.cpp", "tab": "ops", "ln": 26, "tx": "    friend istream& operator>>(istream& in, Point& p);"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "OperatorOverloading.cpp", "tab": "ops", "ln": 27, "tx": "};"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "OperatorOverloading.cpp", "tab": "ops", "ln": 29, "tx": "Point operator*(int k, const Point& p) { return Point(k * p.x_, k * p.y_); }"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "OperatorOverloading.cpp", "tab": "ops", "ln": 31, "tx": "ostream& operator<<(ostream& out, const Point& p) {"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "OperatorOverloading.cpp", "tab": "ops", "ln": 32, "tx": "    out << \"(\" << p.x_ << \", \" << p.y_ << \")\";"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "OperatorOverloading.cpp", "tab": "ops", "ln": 33, "tx": "    return out;                              // lets you chain: cout << a << b"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "OperatorOverloading.cpp", "tab": "ops", "ln": 34, "tx": "}"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "OperatorOverloading.cpp", "tab": "ops", "ln": 36, "tx": "istream& operator>>(istream& in, Point& p) {"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "OperatorOverloading.cpp", "tab": "ops", "ln": 37, "tx": "    in >> p.x_ >> p.y_;"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "OperatorOverloading.cpp", "tab": "ops", "ln": 38, "tx": "    return in;"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "OperatorOverloading.cpp", "tab": "ops", "ln": 39, "tx": "}"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "OperatorOverloading.cpp", "tab": "ops", "ln": 41, "tx": "int main() {"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "OperatorOverloading.cpp", "tab": "ops", "ln": 42, "tx": "    Point a(1, 2), b(3, 4);"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "OperatorOverloading.cpp", "tab": "ops", "ln": 43, "tx": "    cout << \"a + b = \" << a + b << endl;     // (4, 6)"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "OperatorOverloading.cpp", "tab": "ops", "ln": 44, "tx": "    cout << \"b - a = \" << b - a << endl;     // (2, 2)"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "OperatorOverloading.cpp", "tab": "ops", "ln": 45, "tx": "    cout << \"2 * a = \" << 2 * a << endl;     // (2, 4)"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "OperatorOverloading.cpp", "tab": "ops", "ln": 47, "tx": "    a += b;"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "OperatorOverloading.cpp", "tab": "ops", "ln": 48, "tx": "    cout << \"a = \" << a << endl;             // (4, 6)"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "OperatorOverloading.cpp", "tab": "ops", "ln": 50, "tx": "    Point old = a++;                         // postfix returns the OLD value"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "OperatorOverloading.cpp", "tab": "ops", "ln": 51, "tx": "    cout << \"old = \" << old << endl;         // (4, 6)"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "OperatorOverloading.cpp", "tab": "ops", "ln": 52, "tx": "    cout << \"a = \" << a << endl;             // (5, 7)"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "OperatorOverloading.cpp", "tab": "ops", "ln": 53, "tx": "    cout << \"++a = \" << ++a << endl;         // (6, 8)"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "OperatorOverloading.cpp", "tab": "ops", "ln": 55, "tx": "    cout << boolalpha << (a == b) << \" \" << (a != b) << endl;   // false true"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "OperatorOverloading.cpp", "tab": "ops", "ln": 57, "tx": "    // Point c; cin >> c;                    // type \"x y\" to read a point"},
{"p": "code", "f": "code-files.html", "ty": "code", "ti": "OperatorOverloading.cpp", "tab": "ops", "ln": 58, "tx": "}"}
